import boto3
from datetime import datetime, timedelta
from typing import Dict, Any, Tuple

def compare_metric_values(
    region: str,
    namespace: str,
    metric_name: str,
    dimensions1: list[dict],
    dimensions2: list[dict],
    start_time: datetime,
    end_time: datetime,
    period: int = 300,
    stat: str = 'Average'
) -> Dict[str, Any]:
    """
    Compares the specified metric for two sets of dimensions over the same time window.
    Returns average values and their difference.
    """
    client = boto3.client('cloudwatch', region_name=region)

    metric_data_queries = [
        {
            'Id': 'm1',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': dimensions1
                },
                'Period': period,
                'Stat': stat
            },
            'ReturnData': True
        },
        {
            'Id': 'm2',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': dimensions2
                },
                'Period': period,
                'Stat': stat
            },
            'ReturnData': True
        }
    ]

    response = client.get_metric_data(
        MetricDataQueries=metric_data_queries,
        StartTime=start_time,
        EndTime=end_time
    )

    results = {}
    for result in response['MetricDataResults']:
        values = [dp[stat.lower()] for dp in result['Values']]
        avg = sum(values) / len(values) if values else 0.0
        results[result['Id']] = avg

    avg1 = results['m1']
    avg2 = results['m2']
    difference = avg1 - avg2
    ratio = avg2 / avg1 if avg1 != 0 else 0

    return {
        'avg_resource1': avg1,
        'avg_resource2': avg2,
        'difference': difference,
        'ratio_resource2_over_resource1': ratio
    }
